// Some portions generated by Codex
package org.eclipse.rdf4j.sail.lmdb;

import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatThrownBy;

import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.Future;

import org.eclipse.rdf4j.sail.lmdb.LmdbAdjacencyMemoryAccount.MemoryKind;
import org.junit.jupiter.api.Test;

class LmdbAdjacencyBuildWorkspaceTest {

	private static final long WORKSPACE_REGION_BYTES = 1L << 20;

	@Test
	void sparseTwentyBillionPayloadsSpanEveryReferenceType() {
		long highPayload = 20_000_000_000L;
		LmdbAdjacencyMemoryAccount account = new LmdbAdjacencyMemoryAccount(16L << 20);
		List<String> visited = new ArrayList<>();

		try (LmdbAdjacencyBuildWorkspace workspace = new LmdbAdjacencyBuildWorkspace(account,
				WORKSPACE_REGION_BYTES)) {
			workspace.recordGroup(ValueIds.T_URI, highPayload + 4_096, 0);
			workspace.recordGroup(ValueIds.T_URI, highPayload, 1);
			workspace.recordGroup(ValueIds.T_LITERAL, highPayload + 1, 2);
			workspace.recordGroup(ValueIds.T_BNODE, highPayload + 2, 3);
			workspace.recordGroup(ValueIds.T_TRIPLE, highPayload + 3, 0);

			assertThat(workspace.count(ValueIds.T_URI, highPayload, 1)).isEqualTo(1);
			assertThat(workspace.count(ValueIds.T_URI, highPayload + 4_096, 0)).isEqualTo(1);
			assertThat(workspace.maxActivePayloadExclusive(ValueIds.T_TRIPLE)).isEqualTo(highPayload + 4);
			workspace.forEachActiveNode((type, payload, planeCounts) -> visited.add(type + ":" + payload));

			assertThat(visited).containsExactly(
					ValueIds.T_URI + ":" + highPayload,
					ValueIds.T_URI + ":" + (highPayload + 4_096),
					ValueIds.T_LITERAL + ":" + (highPayload + 1),
					ValueIds.T_BNODE + ":" + (highPayload + 2),
					ValueIds.T_TRIPLE + ":" + (highPayload + 3));
			assertThat(workspace.chargedCounterBytes()).isEqualTo(WORKSPACE_REGION_BYTES);
			assertThat(account.chargedBytes(MemoryKind.BUILD_COUNTERS)).isEqualTo(WORKSPACE_REGION_BYTES);
			assertThat(account.chargedBytes(MemoryKind.JAVA_METADATA)).isEqualTo(workspace.chargedJavaBytes());
			assertThat(workspace.chargedJavaBytes()).isPositive();
		}

		assertThat(account.totalChargedBytes()).isZero();
	}

	@Test
	void parallelPlanesShareOnePageWithoutLostUpdates() throws Exception {
		long payload = 400_000_000L;
		int updatesPerPlane = 10_000;
		LmdbAdjacencyMemoryAccount account = new LmdbAdjacencyMemoryAccount(16L << 20);

		try (LmdbAdjacencyBuildWorkspace workspace = new LmdbAdjacencyBuildWorkspace(account, WORKSPACE_REGION_BYTES);
				ExecutorService executor = Executors.newFixedThreadPool(LmdbReferenceNodeLocator.PLANE_COUNT)) {
			List<Future<?>> futures = new ArrayList<>();
			for (int plane = 0; plane < LmdbReferenceNodeLocator.PLANE_COUNT; plane++) {
				int targetPlane = plane;
				futures.add(executor.submit(() -> {
					for (int update = 0; update < updatesPerPlane; update++) {
						workspace.recordGroup(ValueIds.T_URI, payload, targetPlane);
					}
				}));
			}
			for (Future<?> future : futures) {
				future.get();
			}

			assertThat(workspace.activeNodeCount()).isOne();
			assertThat(workspace.groupCount())
					.isEqualTo((long) updatesPerPlane * LmdbReferenceNodeLocator.PLANE_COUNT);
			for (int plane = 0; plane < LmdbReferenceNodeLocator.PLANE_COUNT; plane++) {
				assertThat(workspace.count(ValueIds.T_URI, payload, plane)).isEqualTo(updatesPerPlane);
			}
		}

		assertThat(account.totalChargedBytes()).isZero();
	}

	@Test
	void metadataRefusalReleasesTheOuterDirectory() {
		LmdbAdjacencyMemoryAccount account = new LmdbAdjacencyMemoryAccount(64);

		assertThatThrownBy(() -> {
			try (LmdbAdjacencyBuildWorkspace workspace = new LmdbAdjacencyBuildWorkspace(account,
					WORKSPACE_REGION_BYTES)) {
				workspace.recordGroup(ValueIds.T_URI, 1, 0);
			}
		}).isInstanceOf(LmdbAdjacencyMemoryRefusedException.class)
				.hasMessageContaining("directory root");
		assertThat(account.refusedCount()).isEqualTo(1);
		assertThat(account.totalChargedBytes()).isZero();
	}
}
